// Fit (`fit.tenshu.app`) — a Tenshu app on its own origin (ADR 0020), on the shared app
// preset (`@tenshu/app-kit`, web-app-suite.md F3): Vite + Vitest + Tailwind, the dev server's
// `fs.allow` and the served `manifest.webmanifest`. Generated by scripts/new-web-app.sh.
//
// ⚠ Imported by its file path, not `@tenshu/app-kit/vite`: Node loads this config and refuses to
// strip types from a `.ts` it resolved through `node_modules`. The same for map-kit's glyph plugin.
import { mergeConfig } from 'vite'
import { tenshuAppConfig } from '../app-kit/src/vite.ts'
import { tenshuMapGlyphs } from '../map-kit/src/vite.ts'

// ⚠ No `chunkSizeWarningLimit` override: this bundle must NOT contain the Kotlin runtime, so Vite's
// default 500 kB warning is the tripwire for a stray SDK value import. (MapLibre is its own lazy
// chunk and is expected to exceed it; `bundleSplit.test.ts` pins that it stays separate.)
export default mergeConfig(
  tenshuAppConfig({
    // The apex registry entry (`web/apex/src/apps/registry/apps/fit.ts`) names the same port.
    port: 5180,
    manifest: {
      id: 'fit',
      name: 'Fit',
      description: 'Your activity, end-to-end encrypted.',
      // docs/web/architecture.md §6. Display/declaration data; the apex allowlist is the enforcement.
      semanticPermissions: [
        {
          id: 'tenshu/fit/service',
          humanDescription: 'Read your activity and workouts; import and delete workouts; change your goals and profile',
          scope: ['/'],
        },
        {
          id: 'tenshu/mapregion/service',
          humanDescription: 'Read map regions to draw a workout route',
          scope: ['/'],
        },
      ],
    },
  }),
  // Glyphs from this app's own origin (how-to §2b): no font CDN. `base` matches `<TenshuMap>`'s
  // default `glyphsBase` (`/glyphs`).
  { plugins: [tenshuMapGlyphs()] },
)
